'use strict';
async function start(){
 const loadFeed = async signal => {const response = await fetch('feed.json', {cache:'no-store',signal}); if(!response.ok) throw new Error('Feed unavailable'); const data=await response.json();if(!Array.isArray(data.contexts)||!Array.isArray(data.videos))throw new Error('Invalid feed');return data;};
 const initialController=new AbortController(),initialTimeout=setTimeout(()=>initialController.abort(),10000);
 try{window.SEED=await loadFeed(initialController.signal)}catch{
  const grid=document.getElementById('grid'),warning=document.createElement('p'),retry=document.createElement('button'),pause=document.createElement('button');
  warning.setAttribute('role','alert');warning.textContent='Could not load the local feed. Live may still be on. Pause Live, retry the feed, or stop the service.';
  retry.type='button';retry.textContent='Retry loading the feed';retry.addEventListener('click',()=>{retry.disabled=true;grid.textContent='Retrying…';start().catch(()=>{grid.textContent='Unable to start YourTube. Reload the page to try again.'})});
  pause.type='button';pause.textContent='Pause Live';pause.addEventListener('click',async()=>{if(pause.disabled)return;pause.disabled=true;const controller=new AbortController(),timeout=setTimeout(()=>controller.abort(),10000);try{const response=await fetch('/api/live',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({enabled:false}),signal:controller.signal});if(!response.ok)throw Error();const result=await response.json();if(result.enabled!==false||result.mode!=='paused')throw Error();warning.textContent='Server confirmed Live is paused. Retry loading the feed.'}catch{warning.textContent='Could not confirm Live is paused. Retry, or stop the service to pause it.'}finally{clearTimeout(timeout);pause.disabled=false}});
  grid.replaceChildren(warning,retry,pause);return;
 }finally{clearTimeout(initialTimeout)}
 let feedVersion=JSON.stringify(window.SEED),feedRequest=0;
const $ = id => document.getElementById(id), KEY = 'yourtube.state.v1';
const blank = () => ({contextEdits:{},customContexts:[],deletedContexts:[],customVideos:[],hiddenVideos:[],saved:[]});
let state;
try { state = {...blank(),...JSON.parse(localStorage.getItem(KEY) || '{}')}; } catch { state = blank(); }
let active = window.SEED.focusContext || 'all', view = 'all', liveState = {mode:'connecting', message:'Connecting to local live service.'};
const esc = value => String(value ?? '').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function contexts(){ return [...window.SEED.contexts.map(c=>({...c,...state.contextEdits[c.id]})),...state.customContexts].filter(c=>!state.deletedContexts.includes(c.id)); }
// Prefer a user's manual details where the same video has multiple records.
// Keep separate project associations so each project's filter remains useful.
function collapseVideos(items,key){const manual=new Set(state.customVideos),result=[],positions=new Map();for(const video of items){const k=key(video);if(!positions.has(k)){positions.set(k,result.length);result.push(video)}else if(manual.has(video)&&!manual.has(result[positions.get(k)]))result[positions.get(k)]=video}return result}
function videos(){ const valid = new Set(contexts().map(c=>c.id)); return collapseVideos([...window.SEED.videos,...state.customVideos].filter(v=>valid.has(v.context)&&!state.hiddenVideos.includes(v.id)),v=>JSON.stringify([v.id,v.context])); }
function visibleVideos(all=videos()){const q=$('search').value.trim().toLowerCase();return collapseVideos(all.filter(v=>(active==='all'||v.context===active)&&(view!=='saved'||state.saved.includes(v.id))&&[v.title,v.channel,v.reason].some(s=>String(s||'').toLowerCase().includes(q))),v=>v.id)}
function persist(next){try{localStorage.setItem(KEY,JSON.stringify(next));state=next;return true}catch{toast('Could not save to this browser.');return false}}
let toastTimer;function toast(message){$('toast').textContent=message;$('toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('show'),2800)}
function selectContext(id){active=id;view='all';render()}
function render(){
 const cs=contexts(), all=videos(), current=cs.find(c=>c.id===active); if(active!=='all'&&!current){active='all';return render()}
 $('context-nav').innerHTML=cs.map(c=>`<button class="context-nav ${active===c.id?'selected':''}" data-context="${esc(c.id)}"><span></span>${esc(c.name)}</button>`).join('');
 document.querySelectorAll('.nav').forEach(n=>n.classList.toggle('selected',n.dataset.view===view&&active==='all'));
 $('save-count').textContent=state.saved.filter(id=>all.some(v=>v.id===id)).length||'';
 $('focus-kicker').textContent=current?'CURRENT FOCUS':'YOUR CONTEXT'; $('focus-title').textContent=current?current.name:'A feed that follows your work.'; $('focus-task').textContent=current?current.task:'Choose a project to focus your feed, or explore everything below.';
 $('feed-title').textContent=view==='saved'?'Your watch later list':current?`For ${current.name}`:'Picked for what you’re working on';
 $('feed-subtitle').textContent=view==='saved'?'Videos you saved in this browser.':(window.SEED.contextSource==='Empty starter feed'?'No feed updates yet.':`Curated from recent work · ${window.SEED.updatedAt ? 'Updated '+new Date(window.SEED.updatedAt).toLocaleString() : 'Update time unavailable'}`);
 $('filters').innerHTML=[{id:'all',name:'All'},...cs].map(c=>`<button class="chip ${active===c.id&&view==='all'?'active':''}" data-context="${esc(c.id)}">${esc(c.name)}</button>`).join('') + `<button class="chip ${view==='saved'?'active':''}" data-view="saved">♡ Watch later</button><button class="chip" data-new-context>+ Project</button>`;
 const q=$('search').value.trim().toLowerCase();const found=visibleVideos(all);
 $('grid').innerHTML=found.length?found.map(v=>{const c=cs.find(c=>c.id===v.context);const saved=state.saved.includes(v.id);return `<article class="card"><button class="thumb" data-play="${esc(v.id)}" aria-label="Play ${esc(v.title)}"><img loading="lazy" referrerpolicy="no-referrer" src="https://i.ytimg.com/vi/${esc(v.id)}/hqdefault.jpg" alt=""><span class="play" aria-hidden="true">▶</span></button><div class="card-top"><button class="card-title" data-play="${esc(v.id)}">${esc(v.title)}</button><button class="save ${saved?'is-saved':''}" data-save="${esc(v.id)}" aria-label="${saved?'Remove from':'Add to'} watch later" aria-pressed="${saved}">${saved?'♥':'♡'}</button></div><div class="meta">${esc(v.channel)} · ${esc(c?.name)}</div><div class="reason"><strong>WHY IT'S HERE</strong>${esc(v.reason||'Added to this project by you.')}</div><div class="card-tools"><span>${esc(v.source)}</span><button data-hide="${esc(v.id)}">Remove from feed</button></div></article>`}).join(''):(!q&&view!=='saved'&&!cs.length?`<div class="empty"><h3>Start with a project.</h3><p>Add a project and a video manually, or explore a sample feed. Live chat reading starts paused; review How this works before enabling it.</p><a class="text-button" href="/demo.html">Try a sample feed ↗</a></div>`:`<div class="empty"><h3>Nothing here yet.</h3><p>${q?'Try a different search.':view==='saved'?'Save a video to come back to it later.':'Add a video or ask Codex to update this collection.'}</p></div>`);
}
async function refreshFeed(announce=false){const request=++feedRequest,controller=new AbortController(),timeout=setTimeout(()=>controller.abort(),10000);try{const next=await loadFeed(controller.signal);if(request!==feedRequest)return;const version=JSON.stringify(next);if(version!==feedVersion){window.SEED=next;feedVersion=version;render();if(announce)toast('YourTube updated for your latest work.')}}catch(err){if(request===feedRequest)throw err}finally{clearTimeout(timeout)}}
$('context-nav').addEventListener('click',e=>{const btn=e.target.closest('[data-context]');if(btn)selectContext(btn.dataset.context)});
$('filters').addEventListener('click',e=>{const btn=e.target.closest('[data-context]');if(btn)selectContext(btn.dataset.context);else if(e.target.closest('[data-view]')){active='all';view='saved';render()}else if(e.target.closest('[data-new-context]'))openContext(true)});
$('search').addEventListener('input',render);
document.querySelectorAll('.nav').forEach(button=>button.addEventListener('click',()=>{view=button.dataset.view;active='all';render()}));
$('grid').addEventListener('click',e=>{
 const play=e.target.closest('[data-play]'),save=e.target.closest('[data-save]'),hide=e.target.closest('[data-hide]');
 if(play){const video=visibleVideos().find(v=>v.id===play.dataset.play);if(!video)return;$('player-title').textContent=video.title;$('open-youtube').href=`https://www.youtube.com/watch?v=${video.id}`;const frame=document.createElement('iframe');frame.title=video.title;frame.src=`https://www.youtube-nocookie.com/embed/${video.id}?rel=0`;frame.allow='accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share';frame.referrerPolicy='strict-origin-when-cross-origin';frame.allowFullscreen=true;$('player').replaceChildren(frame);$('player-dialog').showModal()}
 if(save){const id=save.dataset.save,saved=state.saved.includes(id)?state.saved.filter(x=>x!==id):[...state.saved,id];if(persist({...state,saved}))render()}
 if(hide&&confirm('Remove this video from your feed?')){const id=hide.dataset.hide,next={...state,hiddenVideos:[...state.hiddenVideos,id],saved:state.saved.filter(x=>x!==id)};if(persist(next)){render();toast('Video removed from your feed.')}}
});
$('player-dialog').addEventListener('close',()=>$('player').replaceChildren());
document.querySelectorAll('[data-close]').forEach(button=>button.addEventListener('click',()=>$(button.dataset.close).close()));
let contextDialogGeneration=0;const deferredDeletionNotices=[],pendingDeletions=new Set(),uncertainDeletions=new Set();
function contextSaveBlock(id){if(pendingDeletions.has(id))return 'Deletion is in progress. Your draft is still here; wait for the result.';if(uncertainDeletions.has(id))return 'Could not confirm project deletion. Copy your draft and reload to check before saving.';if(state.deletedContexts.includes(id))return 'This project was deleted. Copy your draft, then add a new project to save it.';return ''}
function reportDeletion(message){if(document.querySelector('dialog[open]'))deferredDeletionNotices.push(message);else toast([...deferredDeletionNotices.splice(0),message].join(' '))}
document.querySelectorAll('dialog').forEach(dialog=>dialog.addEventListener('close',()=>{if(!document.querySelector('dialog[open]')&&deferredDeletionNotices.length)toast(deferredDeletionNotices.splice(0).join(' '))}));
function openContext(isNew=false){contextDialogGeneration++;$('context-error').textContent='';const cs=contexts();const context=!isNew?(cs.find(c=>c.id===active)||cs[0]):null;$('context-dialog-title').textContent=context?'Edit your context':'Add a project';$('context-id').value=context?.id||'';$('context-name').value=context?.name||'';$('context-task').value=context?.task||'';$('context-note').value=context?.note||'';$('delete-context').hidden=!context;$('context-error').textContent=context?contextSaveBlock(context.id):'';$('context-dialog').showModal()}
$('add-context').addEventListener('click',()=>openContext(true));$('edit-context').addEventListener('click',()=>openContext(false));$('focus-edit').addEventListener('click',()=>openContext(false));$('how-it-works').addEventListener('click',()=>{$('context-source').textContent='Context used for this collection: '+(window.SEED.contextSource||'Not specified')+'.';$('live-detail').textContent=liveState.message+(liveState.lastSearch?' Last general search: '+liveState.lastSearch:'');$('info-dialog').showModal()});
$('context-form').addEventListener('submit',e=>{e.preventDefault();const previousError=$('context-error').textContent;$('context-error').textContent='';const id=$('context-id').value||crypto.randomUUID();const item={id,name:$('context-name').value.trim(),task:$('context-task').value.trim(),note:$('context-note').value.trim()};if(!item.name||!item.task)return;const blocked=contextSaveBlock(id);if(blocked){const partial=previousError.includes('Browser changes could not be saved')?' Browser changes could not be saved and may reappear after reload.':'';$('context-error').textContent=blocked+partial;return}const next=window.SEED.contexts.some(c=>c.id===id)?{...state,contextEdits:{...state.contextEdits,[id]:item}}:{...state,customContexts:[...state.customContexts.filter(c=>c.id!==id),item]};if(!persist(next)){$('context-error').textContent='Could not save to this browser. Your draft is still here; try again.';return}$('context-dialog').close();active=id;view='all';render();toast('Context saved in this browser.')});
$('delete-context').addEventListener('click',async()=>{$('context-error').textContent='';const id=$('context-id').value,generation=contextDialogGeneration;if(!id)return;if(pendingDeletions.has(id)){$('context-error').textContent=contextSaveBlock(id);return}if(!confirm('Delete this project, its saved context and its videos from YourTube?'))return;pendingDeletions.add(id);const sameDialog=()=>$('context-dialog').open&&$('context-id').value===id,originalDialog=()=>sameDialog()&&contextDialogGeneration===generation;const controller=new AbortController(),timeout=setTimeout(()=>controller.abort(),10000);let response;try{response=await fetch('/api/context/delete',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({id}),signal:controller.signal});if(!response.ok)throw Error()}catch{uncertainDeletions.add(id);const message='Could not confirm project deletion. Reconnect or reload to check.';if(sameDialog())$('context-error').textContent='Could not confirm project deletion. Copy your draft and reload to check before saving.';else reportDeletion(message);return}finally{clearTimeout(timeout);pendingDeletions.delete(id)}uncertainDeletions.delete(id);const edits={...state.contextEdits};delete edits[id];const next={...state,deletedContexts:[...state.deletedContexts,id],customContexts:state.customContexts.filter(c=>c.id!==id),contextEdits:edits,customVideos:state.customVideos.filter(v=>v.context!==id)};const saved=persist(next);if(!saved)state=next;if(originalDialog())$('context-dialog').close();else if(sameDialog())$('context-error').textContent=contextSaveBlock(id)+(!saved?' Browser changes could not be saved and may reappear after reload.':'');let refreshed=true;try{await refreshFeed()}catch{refreshed=false}if(active===id)active='all';render();reportDeletion(!saved?'Server accepted deletion, but browser changes could not be saved and may reappear after reload.':!refreshed?'Project deleted, but the feed could not be refreshed. Reload to check.':'Project and its saved context deleted.')});
$('add-video').addEventListener('click',()=>{const cs=contexts();if(!cs.length){toast('Add a project first.');return}$('video-form').reset();$('video-error').textContent='';$('video-context').innerHTML=cs.map(c=>`<option value="${esc(c.id)}">${esc(c.name)}</option>`).join('');if(active!=='all')$('video-context').value=active;$('video-dialog').showModal()});
function parseVideoId(value){try{const u=new URL(value);let id='';if(u.hostname==='youtu.be')id=u.pathname.split('/')[1];else if(['youtube.com','www.youtube.com','m.youtube.com'].includes(u.hostname))id=u.pathname==='/watch'?u.searchParams.get('v'):(u.pathname.match(/^\/(?:shorts|embed)\/([^/]+)/)||[])[1];return /^[a-zA-Z0-9_-]{11}$/.test(id||'')?id:null}catch{return null}}
$('video-form').addEventListener('submit',e=>{e.preventDefault();$('video-error').textContent='';const project=$('video-context').value;if(pendingDeletions.has(project)){$('video-error').textContent='Project deletion is in progress. Your video draft is still here; wait for the result or choose another project.';return}if(uncertainDeletions.has(project)){$('video-error').textContent='Could not confirm whether this project was deleted. Choose another project, or copy your draft and reload to check.';return}if(state.deletedContexts.includes(project)||!contexts().some(c=>c.id===project)){$('video-error').textContent='This project is deleted or unavailable. Choose another project to save your video draft.';return}const id=parseVideoId($('video-url').value.trim());if(!id){$('video-error').textContent='Enter a valid YouTube video link.';return}if(videos().some(v=>v.id===id)){$('video-error').textContent='This video is already in your feed.';return}const item={id,title:$('video-title').value.trim(),channel:$('video-channel').value.trim()||'YouTube',context:$('video-context').value,reason:$('video-reason').value.trim(),source:'Added by you'};if(!item.title)return;const next={...state,hiddenVideos:state.hiddenVideos.filter(x=>x!==id),customVideos:[...state.customVideos,item]};if(!persist(next)){$('video-error').textContent='Could not save to this browser. Your draft is still here; try again.';return}$('video-dialog').close();active=item.context;view='all';render();toast('Video added to your feed.')});
render();

 let statusReady=false,liveRequestPending=false,events,feedRetry=null,feedSyncGeneration=0;
 function cancelFeedRetry(){feedSyncGeneration++;if(feedRetry!==null){clearTimeout(feedRetry);feedRetry=null}}
 function connectEvents(){
  if(events)events.close();cancelFeedRetry();feedRequest++;statusReady=false;$('live-toggle').disabled=true;
  const current=events=new EventSource('/events');
  current.addEventListener('status',e=>{if(events!==current)return;try{const next=JSON.parse(e.data);if(typeof next.enabled!=='boolean'||typeof next.mode!=='string')throw Error('Invalid status');liveState=next;$('watcher-warning').hidden=!liveState.enabled||liveState.activityMayBeMissed!==true;statusReady=true;$('live-toggle').disabled=liveRequestPending;if(liveState.enabled!==false&&$('live-consent').open)$('live-consent').close();$('live-label').textContent=liveState.mode==='paused'?'Paused':liveState.mode==='error'&&!liveState.watcherReady?'Retry':liveState.mode==='error'?'Live issue':liveState.mode==='awaiting-review'?'Review search':liveState.mode==='curating'||liveState.mode==='searching'||liveState.mode==='waiting'?'Updating…':'Live';$('live-toggle').title=liveState.message;$('live-toggle').classList.toggle('paused',liveState.mode==='paused'||liveState.mode==='error');if($('info-dialog').open)$('live-detail').textContent=liveState.message+(liveState.lastSearch?' Last general search: '+liveState.lastSearch:'');if(liveState.mode==='awaiting-review'&&liveState.requestId&&!$('search-review').open){$('search-review-query').value=liveState.pendingQuery||'';$('search-review-error').textContent='';$('search-review').showModal()}else if(liveState.mode!=='awaiting-review'&&$('search-review').open)$('search-review').close()}catch{statusReady=false;$('live-toggle').disabled=true}});
  const syncFeed=()=>{if(events!==current)return;cancelFeedRetry();const generation=feedSyncGeneration;const attempt=number=>{if(events!==current||generation!==feedSyncGeneration)return;refreshFeed(true).catch(()=>{if(events!==current||generation!==feedSyncGeneration)return;if(number<3){feedRetry=setTimeout(()=>{feedRetry=null;attempt(number+1)},1000*2**number)}else toast('Could not load the updated feed. Reconnect or reload to try again.')})};attempt(0)};
  current.addEventListener('open',syncFeed);
  current.addEventListener('feed',syncFeed);
  current.onerror=()=>{if(events!==current)return;cancelFeedRetry();feedRequest++;statusReady=false;if($('live-consent').open)$('live-consent').close();liveState={mode:'disconnected',message:'Live service disconnected. Restart YourTube.'};$('live-label').textContent='Offline';$('live-toggle').disabled=true;$('live-toggle').classList.add('paused')};
 }
 connectEvents();
 async function setLive(enabled){if(liveRequestPending||!statusReady||typeof liveState.enabled!=='boolean')return;const expectedEnabled=liveState.enabled;statusReady=false;liveRequestPending=true;$('live-toggle').disabled=true;const controller=new AbortController(),timeout=setTimeout(()=>controller.abort(),10000);try{const response=await fetch('/api/live',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({enabled,expectedEnabled}),signal:controller.signal});if(!response.ok)throw Error()}catch{toast('Could not change Live. Reconnecting to check its status.')}finally{clearTimeout(timeout);liveRequestPending=false;connectEvents()}}
 $('live-toggle').addEventListener('click',()=>{if(!statusReady||liveRequestPending||typeof liveState.enabled!=='boolean')return;if(liveState.enabled)setLive(false);else if(!$('live-consent').open)$('live-consent').showModal()});
 $('live-consent-cancel').addEventListener('click',()=>$('live-consent').close());
 $('live-consent-form').addEventListener('submit',e=>{e.preventDefault();if(!$('live-consent').open)return;$('live-consent').close();if(statusReady&&liveState.enabled===false)setLive(true)});
 async function reviewSearch(action){try{const response=await fetch('/api/search-review',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({requestId:liveState.requestId,action,query:$('search-review-query').value})});if(!response.ok)throw Error();}catch{$('search-review-error').textContent='Could not process that request. Use a general phrase without links, email addresses, or credentials.'}}
 $('search-review-form').addEventListener('submit',e=>{e.preventDefault();reviewSearch('approve')});
 $('search-review-cancel').addEventListener('click',()=>reviewSearch('cancel'));
 $('search-review').addEventListener('cancel',e=>{e.preventDefault();reviewSearch('cancel')});
}
start().catch(()=>{document.getElementById('grid').textContent='Unable to load the local feed. Make sure YourTube is running through its local server.'});
